package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                        // PIC X len=1 = "N"
var WsLabel string = strings.Repeat(" ", 20)     // PIC X(20) len=20 = SPACES
var WsACount int64 = 0                           // PIC 99 len=2 = 0
var WsTotalA int64 = 0                           // PIC 999 len=3 = 0
var WsCount int64 = 0                            // PIC 999 len=3 = 0

var currentPartRec PartRec
var inputLines []string
var inputIdx int

// to avoid unused import error if decimal not otherwise used
var _ = decimal.NewFromInt

func InputDone() bool { return WsEofFlag == "Y" }

func formatNum(v int64, digits int) string {
	// high-order truncation already done on store; just format
	// handle negative? not needed here
	if v < 0 {
		v = -v
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	v = v % mod
	return fmt.Sprintf("%0*d", digits, v)
}

func delimitedBySpace(s string) string {
	idx := strings.Index(s, " ")
	if idx == -1 {
		return s
	}
	return s[:idx]
}

func serialString() string {
	// PIC 9(4) display is zero padded 4 digits, DELIMITED BY SIZE
	// low-order truncation to 4 digits
	v := currentPartRec.LbSerial % 10000
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%04d", v)
}

func stringInto(target, src string) string {
	tb := []byte(target)
	sb := []byte(src)
	n := len(sb)
	if n > len(tb) {
		n = len(tb)
	}
	for i := 0; i < n; i++ {
		tb[i] = sb[i]
	}
	return string(tb)
}

func OpenPartFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty (COBOL would error, but we exit)
		inputLines = []string{}
		inputIdx = 0
		return
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)
	for scanner.Scan() {
		line := scanner.Text()
		// Scanner strips \r from \r\n, keep everything else including trailing spaces
		// If file was written with CRLF, the \r is removed.
		inputLines = append(inputLines, line)
	}
	// ignore scanner.Err for now
	inputIdx = 0
}

func ClosePartFile() {
	// nothing to do
}

func MainPara() {
	OpenPartFile()
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	ClosePartFile()
	SummaryPara()
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++

	// COBOL LINE SEQUENTIAL: pad with spaces on right if shorter than record length
	const recLen = 15
	if len(line) < recLen {
		line = line + strings.Repeat(" ", recLen-len(line))
	} else if len(line) > recLen {
		line = line[:recLen]
	}
	// parse fields
	lbPart := line[0:8]
	lbRegion := line[8:11]
	lbSerialStr := line[11:15]

	var serialVal int64 = 0
	trimmed := strings.TrimSpace(lbSerialStr)
	if trimmed != "" {
		// serial is digits only, may have leading zeros
		// use TrimSpace already, parse
		if v, err := strconv.ParseInt(trimmed, 10, 64); err == nil {
			serialVal = v
		} else {
			// if parse fails (non-numeric), treat as 0
			serialVal = 0
		}
		// truncate to 4 digits (high-order dropped)
		serialVal = serialVal % 10000
		if serialVal < 0 {
			serialVal = -serialVal
		}
	} else {
		serialVal = 0
	}

	currentPartRec = PartRec{
		LbPart:   lbPart,
		LbRegion: lbRegion,
		LbSerial: serialVal,
	}
}

func ProcessPara() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	// count occurrences of "A" in LB-PART
	cnt := int64(strings.Count(currentPartRec.LbPart, "A"))
	WsACount = cnt % 100 // PIC 99 truncation
	// STRING ...
	seg1 := delimitedBySpace(currentPartRec.LbRegion)
	seg2 := "-"
	seg3 := delimitedBySpace(currentPartRec.LbPart)
	seg4 := "-"
	seg5 := serialString()
	combined := seg1 + seg2 + seg3 + seg4 + seg5
	WsLabel = stringInto(WsLabel, combined)
	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")
	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA = (WsTotalA + WsACount) % 1000
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 1000
	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL is PIC X(20) -> exactly 20 chars
	// " A=" literal
	// WS-A-COUNT PIC 99 -> zero padded 2 digits
	out := WsLabel + " A=" + formatNum(WsACount, 2) + "\n"
	os.Stdout.WriteString(out)
	ReadPara()
}

func SummaryPara() {
	// DISPLAY "LABELS: " WS-COUNT " A-TOTAL: " WS-TOTAL-A.
	out := "LABELS: " + formatNum(WsCount, 3) + " A-TOTAL: " + formatNum(WsTotalA, 3) + "\n"
	os.Stdout.WriteString(out)
}

func main() {
	MainPara()
}
